css:
h2::before{content:"";display:block;width:32px;height:1px;background:#c9a227;margin-bottom:26px}
/* 縦組みの頭に立てる */
.vcap{writing-mode:vertical-rl;font-size:10px;letter-spacing:.3em}
.vcap::before{content:"";display:block;width:1px;height:60px;margin:0 auto 12px;background:rgba(255,255,255,.85)}
/* 写真の中へ垂らす */
.drop{position:absolute;left:50%;top:0;width:1px;height:80px;background:linear-gradient(#c9ab68,rgba(201,171,104,0))}
.drop::after{content:"";position:absolute;top:58px;left:-5px;width:11px;height:11px;background:url(star.svg) center/contain no-repeat}
